def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    explored = set()  # Set to keep track of explored nodes
    priority_queue = [(start, [start])]  # Priority queue for BFS-like behavior, here we use a simple list

    while priority_queue:
        (node, path) = priority_queue.pop(0)  # FIFO queue behavior

        if node in explored:
            continue

        explored.add(node)

        if node == goal:
            return path

        for neighbor in graph[node]:
            if neighbor not in explored:
                priority_queue.append((neighbor, path + [neighbor]))  # Append the neighbor with the current path

    return None

