def find_path(graph, start, goal):
    from collections import deque

    def bfs_with_cycle_detection(graph, start, goal):
        visited = set()
        queue = deque([(start, [start])])
        while queue:
            current, path = queue.popleft()
            if current not in visited:
                visited.add(current)
                if current == goal:
                    return path
                for neighbor in graph.get(current, []):
                    if neighbor not in visited and neighbor not in path:
                        queue.append((neighbor, path + [neighbor]))
        return None

    def find_path_without_cycle_detection(graph, start, goal):
        visited = set()
        stack = [(start, [start])]
        while stack:
            current, path = stack.pop()
            if current not in visited:
                visited.add(current)
                if current == goal:
                    return path
                for neighbor in graph.get(current, []):
                    if neighbor not in visited:
                        stack.append((neighbor, path + [neighbor]))
        return None

    # Use BFS with cycle detection to find a path
    path = bfs_with_cycle_detection(graph, start, goal)
    if path:
        return path

    # If cycle detection didn't find a path, try again without cycle detection
    path = find_path_without_cycle_detection(graph, start, goal)
    if path:
        return path

    return None

