def find_path(graph, start, goal):
    # Initialize the path dictionary to keep track of the shortest distance to the goal node
    path = {node: float('inf') for node in graph}
    parent = {node: None for node in graph}
    path[start] = 0
    # Queue to keep track of the nodes to visit
    queue = [start]

    while queue:
        current = queue.pop(0)
        if current == goal:
            # Reconstruct the path from start to goal using parent dictionary
            result = []
            while current is not None:
                result.append(current)
                current = parent[current]
            return result[::-1]
        for neighbor in graph[current]:
            if path[current] + 1 < path[neighbor]:
                path[neighbor] = path[current] + 1
                parent[neighbor] = current
                queue.append(neighbor)
    return None
